"use strict";const essentialIds=["linvocation_complete_de_listikhara","yunus_21_87","musa_28_24","musa_ease_20_25_28","ayyub_21_83","quran_25_74","quran_3_38","quran_14_40","quran_2_201","debt_anxiety","healing_prophetic","halal_sufficiency","beneficial_rizq","knowledge_20_114","hasbunallah_3_173","sayyid_istighfar","travel_dua","protection_children","morning_evening_protection","parents_17_24"],grid=document.getElementById("essentialDuasGrid"),loading=document.getElementById("essentialDuasLoading");async function loadEssentialDuas(){try{const e=await fetch("../data/duas.json?v=20",{cache:"no-store"});if(!e.ok)throw new Error(`Erreur HTTP ${e.status}`);const a=await e.json(),n=essentialIds.map(e=>a.duas.find(a=>a.id===e)).filter(Boolean),t=a.duas.filter(e=>!n.some(a=>a.id===e.id)),r=[...n,...t].slice(0,20);grid.innerHTML=r.map(e=>createEssentialCard(e,a.categories)).join(""),loading.classList.add("hidden")}catch(e){console.error("Impossible de charger les douaas essentielles :",e),loading.textContent="La sélection n’a pas pu être chargée pour le moment."}}function createEssentialCard(e,a){const n=Array.isArray(e.categories)?e.categories[0]:null,t=a.find(e=>e.id===n),r=e.title||(t?`Douaa : ${t.label}`:"Invocation essentielle"),_=Array.isArray(e.whenToRead)&&e.whenToRead.length?e.whenToRead[0]:e.meaning||e.context||"Découvrir le texte et son explication.";return`\n    <a\n      class="essential-dua-card"\n      href="${"linvocation_complete_de_listikhara"===e.id?"../priere-de-consultation/":getEssentialUrl(e.id)}"\n    >\n      <span class="essential-number">✦</span>\n      <strong>${escapeHtml(r)}</strong>\n      <span>${escapeHtml(_)}</span>\n      <small>${escapeHtml(e.source||e.referenceDetails||"")}</small>\n    </a>\n  `}document.addEventListener("DOMContentLoaded",loadEssentialDuas);const staticEssentialIds=new Set(["ayyub_21_83","beneficial_rizq","debt_anxiety","guidance_3_8","halal_sufficiency","hasbunallah_3_173","healing_prophetic","knowledge_20_114","musa_28_24","musa_ease_20_25_28","parents_17_24","protection_words","quran_3_38","quran_14_40","quran_25_74","yunus_21_87","quran_2_286_burden","quran_3_16_forgiveness","quran_3_147_steadfastness","quran_14_41_family_forgiveness","quran_18_10_right_guidance","quran_23_97_98_whispers","quran_40_7_9_family_paradise","quran_46_15_righteous_descendants","quran_59_10_no_resentment","quran_66_8_complete_light","quran_71_28_believers_forgiveness","prophetic_religion_world_hereafter","prophetic_guidance_piety_chastity","prophetic_wronged_self","prophetic_pardon_afuw","prophetic_help_worship","prophetic_love_allah","prophetic_distress_tawhid","prophetic_distress_allah_rabbi","prophetic_calamity_reward","prophetic_refuge_wrongdoing","prophetic_funeral_all_muslims","prophetic_graveyard_greeting","prophetic_deceased_reward","prophetic_healing_ruqya","prophetic_healing_seven_times","prophetic_spouse_goodness","prophetic_before_intimacy","prophetic_all_good","prophetic_bad_character_refuge","prophetic_refuge_poverty","prophetic_refuge_severe_trial","prophetic_useless_knowledge"]);function getEssentialUrl(e){return staticEssentialIds.has(e)?`../douaas/${e.replaceAll("_","-")}/`:`../douaa.html?id=${encodeURIComponent(e)}`}function escapeHtml(e){return String(e??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}